@math_server.tool
def add(a: float, b: float) -> float:
    """Add two numbers."""
    return a + b

@math_server.tool
def multiply(a: float, b: float) -> float:
    """Multiply two numbers."""
    return a * b

@math_server.tool
def divide(a: float, b: float) -> float:
    """Divide two numbers."""
    if b == 0:
        raise ValueError("Cannot divide by zero")
    return a / b

@math_server.tool
def subtract(a: float, b: float) -> float:
    """Subtract two numbers."""
    return a - b

# Create main server
main_server = FastMCP(name="main_server", instructions="Main server with mounted math tools")

# Mount math_server under "math" namespace
main_server.mount(math_server, namespace="math")

# Add a sample tool to main server
@main_server.tool
def hello(name: str) -> str:
